/*
  карта.js — КАРТА МИРА: дороги, дома, движение героя, камера.

  Чем отличается от ход.js: там переходы между экранами, лавка, стол и
  разговор. Здесь одна вещь — двор снаружи: как он устроен, как по нему
  бежит герой и куда смотрит камера. Своё время, свой шаг кадра.

  Главное в устройстве: у героя НЕТ координат. Есть дорога и одно число —
  пройденный по ней путь. Точку на дороге считает сам браузер через
  getPointAtLength. Отсюда и повороты по кривой без единой формулы.

  Дороги — сеть, а не дерево: каждая знает соседей и место стыка. Путь
  ищется обходом в ширину, поэтому из третьего кольца в первое герой
  идёт через ближний луч, а не вокруг.

  Текстов здесь нет: они в мир.js. Чисел нет: они в настройки.js.
*/

'use strict';

window.КАРТА = (function () {

  const НАСТРОЙКИ = window.МИР_НАСТРОЙКИ;
  const МИР       = window.МИР_ДАННЫЕ;

  const $ = (ид) => document.getElementById(ид);

  /*  Запись героя держит ход.js — он один читает хранилище. Карта
      спрашивает в миг отрисовки, а не при загрузке: ход.js
      подключается после неё.                                     */
  const ЗАПИСЬ = () => (window.ХОД && window.ХОД.герой) ? window.ХОД.герой() : null;
  const НП = 'http://www.w3.org/2000/svg';

  let дороги = [];          // все рёбра сети
  let поКлючу = {};
  let герой = null;         // { дорога, s, вперёд, v, качание }
  let маршрут = [];         // очередь: куда идём дальше
  let приходе = null;       // что сделать, когда дошли
  let камера = null;        // { x, y, цельX, цельY, свободна }
  let полосаТаймер = 0;
  let кадр = 0, прошлое = 0;

  /* ═══ 1 · ГЕОМЕТРИЯ ═══════════════════════════════════════════════ */

  function радианы(градусы) {
    return градусы / НАСТРОЙКИ.карта.полныйОборот * Math.PI * 2;
  }

  function точка(радиус, градусы) {
    const у = радианы(градусы);
    const ц = НАСТРОЙКИ.карта.центр;
    return { x: ц + Math.cos(у) * радиус, y: ц + Math.sin(у) * радиус };
  }

  function кольцоПо(ключ) {
    return МИР.кольца.find((к) => к.ключ === ключ);
  }

  /* ═══ 2 · ДОРОГИ ══════════════════════════════════════════════════
     Кольцо строится ломаной из множества точек, а не дугой. Так длина
     по углу считается точно: доля угла равна доле длины. С дугами
     пришлось бы гадать, откуда браузер начинает отсчёт.            */

  function путьКольца(радиус) {
    const н = НАСТРОЙКИ.карта.точекНаКруге;
    const шаг = НАСТРОЙКИ.карта.полныйОборот / н;
    let d = '';
    for (let i = 0; i < н; i++) {
      const т = точка(радиус, i * шаг);
      d += (i === 0 ? 'M' : 'L') + т.x.toFixed(2) + ' ' + т.y.toFixed(2) + ' ';
    }
    return d + 'Z';
  }

  function создатьПуть(d, класс) {
    const п = document.createElementNS(НП, 'path');
    п.setAttribute('d', d);
    п.setAttribute('class', класс);
    return п;
  }

  function добавитьДорогу(ключ, вид, путь, вес, круговое) {
    const дорога = {
      ключ: ключ, вид: вид, элемент: путь, вес: вес, круговое: !!круговое,
      длина: путь.getTotalLength(), соседи: []
    };
    дороги.push(дорога);
    поКлючу[ключ] = дорога;
    return дорога;
  }

  function связать(а, sА, б, sБ) {
    а.соседи.push({ ключ: б.ключ, sЗдесь: sА, sТам: sБ });
    б.соседи.push({ ключ: а.ключ, sЗдесь: sБ, sТам: sА });
  }

  /* Долгота на кольце по углу: доля оборота равна доле длины. */
  function долготаНаКольце(дорога, градусы) {
    const оборот = НАСТРОЙКИ.карта.полныйОборот;
    let г = ((градусы % оборот) + оборот) % оборот;
    return дорога.длина * г / оборот;
  }

  function построитьДороги() {
    const слой = $('дороги');
    слой.textContent = '';
    дороги = []; поКлючу = {};

    // кольцевые дороги
    for (const к of МИР.кольца) {
      const п = создатьПуть(путьКольца(к.радиус), 'дорога кольцевая');
      слой.appendChild(п);
      добавитьДорогу(к.ключ, МИР.виды.кольцо, п, 1, true);
    }

    // лучи: от кольца к кольцу, по одному ребру на переход
    for (const угол of МИР.лучи) {
      for (let i = 0; i < МИР.кольца.length - 1; i++) {
        const внутр = МИР.кольца[i], внешн = МИР.кольца[i + 1];
        const а = точка(внутр.радиус, угол), б = точка(внешн.радиус, угол);
        const п = создатьПуть('M' + а.x.toFixed(2) + ' ' + а.y.toFixed(2) +
                              'L' + б.x.toFixed(2) + ' ' + б.y.toFixed(2),
                              'дорога лучевая');
        слой.appendChild(п);
        const луч = добавитьДорогу(МИР.виды.луч + '-' + угол + '-' + внутр.ключ,
                                   МИР.виды.луч, п, НАСТРОЙКИ.ход.луч);
        связать(луч, 0, поКлючу[внутр.ключ], долготаНаКольце(поКлючу[внутр.ключ], угол));
        связать(луч, луч.длина, поКлючу[внешн.ключ], долготаНаКольце(поКлючу[внешн.ключ], угол));
      }
    }

    // тропки к домам
    for (const дом of МИР.дома) {
      const к = кольцоПо(дом.кольцо);
      const сторона = дом.сторона === МИР.стороны.внутри ? -1 : 1;
      const радиусДома = к.радиус + сторона * НАСТРОЙКИ.карта.отступДома;
      const а = точка(к.радиус, дом.угол), б = точка(радиусДома, дом.угол);
      const п = создатьПуть('M' + а.x.toFixed(2) + ' ' + а.y.toFixed(2) +
                            'L' + б.x.toFixed(2) + ' ' + б.y.toFixed(2),
                            'дорога тропка');
      слой.appendChild(п);
      const тропка = добавитьДорогу(МИР.виды.тропка + '-' + дом.ключ,
                                    МИР.виды.тропка, п, НАСТРОЙКИ.ход.тропка);
      связать(тропка, 0, поКлючу[дом.кольцо], долготаНаКольце(поКлючу[дом.кольцо], дом.угол));
      дом.тропка = тропка.ключ;
      дом.точка = б;
    }
  }

  /* ═══ 2а · СТЕНА ══════════════════════════════════════════════════
     Высокая замкнутая стена по внешнему краю города. Рисуется кодом,
     как и всё остальное.

     Три её дела, и все три важны:

     ЗАКРЫВАЕТ ВИД. За стеной сплошной камень до самого края холста —
     ни снега, ни пустоты, ни линии горизонта. Там край мира, и он не
     должен выглядеть обрывом.

     ЧИТАЕТСЯ С ТЕЛЕФОНА. Толщина и зубцы взяты от размера экрана, а
     не на глаз: при обзоре 700 на телефоне в 390 точек единица мира
     это 0.56 точки, стена в 70 единиц — 39 точек.

     ДЕРЖИТ СВЕТ СЛЕВА СВЕРХУ, как дома и фигурка. Освещённая половина
     кладки — та, что обращена к свету, дальняя лежит в тени.       */

  function точкиДуги(радиус, отГрадусов, доГрадусов, шагов) {
    const точки = [];
    for (let i = 0; i <= шагов; i++) {
      точки.push(точка(радиус, отГрадусов + (доГрадусов - отГрадусов) * i / шагов));
    }
    return точки;
  }

  const вПуть = (точки, начало) =>
    начало + точки.map((т) => t2(т.x) + ' ' + t2(т.y)).join('L');
  const t2 = (ч) => ч.toFixed(1);

  /*  Кольцо кладки: два круга, между ними заливка. Рисуется одной
      фигурой с правилом «чёт-нечет» — так дырка внутри остаётся
      прозрачной, и город сквозь неё виден.                         */
  function кольцоКладки(внутри, снаружи, класс) {
    const ц = НАСТРОЙКИ.карта.центр;
    const круг = (р) => 'M' + t2(ц - р) + ' ' + t2(ц) +
      'a' + t2(р) + ' ' + t2(р) + ' 0 1 0 ' + t2(р * 2) + ' 0' +
      'a' + t2(р) + ' ' + t2(р) + ' 0 1 0 ' + t2(-р * 2) + ' 0Z';
    const п = document.createElementNS(НП, 'path');
    п.setAttribute('d', круг(снаружи) + круг(внутри));
    п.setAttribute('fill-rule', 'evenodd');
    п.setAttribute('class', класс);
    return п;
  }

  function зубцыСтены(снаружи) {
    const с = НАСТРОЙКИ.карта.стена;
    const оборот = НАСТРОЙКИ.карта.полныйОборот;
    const шаг = оборот / с.зубцов;
    const наружу = снаружи + с.зубец;
    let d = '';
    for (let i = 0; i < с.зубцов; i++) {
      const от = i * шаг, до = от + шаг * с.доляЗубца;
      const низ = точкиДуги(снаружи, от, до, с.шаговЗубца);
      const верх = точкиДуги(наружу, до, от, с.шаговЗубца);
      d += вПуть(низ.concat(верх), 'M') + 'Z';
    }
    const п = document.createElementNS(НП, 'path');
    п.setAttribute('d', d);
    п.setAttribute('class', 'зубцы');
    return п;
  }

  /*  Ворота. Сейчас закрыты и не нажимаются — просто видны. Через них
      потом пойдёт выход на следующую карту.                        */
  function ворота(внутри, снаружи) {
    const с = НАСТРОЙКИ.карта.стена;
    const г = document.createElementNS(НП, 'g');
    г.setAttribute('class', 'ворота');
    for (const угол of с.ворот) {
      const от = угол - с.воротаПоУглу, до = угол + с.воротаПоУглу;
      const проём = document.createElementNS(НП, 'path');
      проём.setAttribute('d', вПуть(
        точкиДуги(внутри, от, до, с.шаговВорот)
          .concat(точкиДуги(снаружи, до, от, с.шаговВорот)), 'M') + 'Z');
      проём.setAttribute('class', 'проём');
      г.appendChild(проём);

      // две створки, сходящиеся посередине
      const середина = (от + до) / 2;
      for (const [а, б] of [[от, середина - (середина - от) * (1 - с.створка)],
                            [до, середина + (до - середина) * (1 - с.створка)]]) {
        const створка = document.createElementNS(НП, 'path');
        створка.setAttribute('d', вПуть(
          точкиДуги(внутри, а, б, с.шаговСтворки)
            .concat(точкиДуги(снаружи, б, а, с.шаговСтворки)), 'M') + 'Z');
        створка.setAttribute('class', 'створка');
        г.appendChild(створка);
      }
    }
    return г;
  }

  function стена() {
    const слой = $('стена');
    слой.textContent = '';
    const с = НАСТРОЙКИ.карта.стена;
    const внутри = с.внутри, снаружи = внутри + с.толщина;

    /*  ЗА СТЕНОЙ. Прямоугольник во весь холст с вырезанным кругом
        города: всё, что снаружи, залито камнем до края.           */
    const край = document.createElementNS(НП, 'path');
    const ц = НАСТРОЙКИ.карта.центр;
    /*  Заграничье шире холста втрое: камера отъезжает от героя, и край
        холста иначе виден прямой чертой — тем самым обрывом.       */
    const от = -НАСТРОЙКИ.карта.холст, х = НАСТРОЙКИ.карта.холст * 2;
    край.setAttribute('d',
      'M' + от + ' ' + от + 'H' + х + 'V' + х + 'H' + от + 'Z' +
      'M' + t2(ц - снаружи) + ' ' + t2(ц) +
      'a' + t2(снаружи) + ' ' + t2(снаружи) + ' 0 1 0 ' + t2(снаружи * 2) + ' 0' +
      'a' + t2(снаружи) + ' ' + t2(снаружи) + ' 0 1 0 ' + t2(-снаружи * 2) + ' 0Z');
    край.setAttribute('fill-rule', 'evenodd');
    край.setAttribute('class', 'закрай');
    слой.appendChild(край);

    слой.appendChild(зубцыСтены(снаружи));
    слой.appendChild(кольцоКладки(внутри, снаружи, 'кладка'));

    /*  Освещённая половина: дуга по стороне, обращённой к свету.
        Свет слева сверху, значит светлая часть — верхняя левая.   */
    const светлая = document.createElementNS(НП, 'path');
    светлая.setAttribute('d', вПуть(
      точкиДуги(внутри, с.светОт - с.полукруг, с.светОт + с.полукруг,
                с.шаговСвета), 'M'));
    светлая.setAttribute('class', 'кладка-свет');
    слой.appendChild(светлая);

    слой.appendChild(ворота(внутри, снаружи));
  }

  /* ═══ 3 · ПОИСК ПУТИ ══════════════════════════════════════════════
     Обход в ширину по сети дорог. Без него герой на восьми лучах
     ходит глупо, и это видно с первого раза.                        */

  function найтиПуть(откуда, куда) {
    if (откуда === куда) return [];
    const пришли = { [откуда]: null };
    const очередь = [откуда];
    while (очередь.length) {
      const текущая = очередь.shift();
      for (const сосед of поКлючу[текущая].соседи) {
        if (сосед.ключ in пришли) continue;
        пришли[сосед.ключ] = { из: текущая, стык: сосед };
        if (сосед.ключ === куда) {
          const шаги = [];
          let к = куда;
          while (пришли[к]) {
            шаги.unshift({ дорога: к, стык: пришли[к].стык });
            к = пришли[к].из;
          }
          return шаги;
        }
        очередь.push(сосед.ключ);
      }
    }
    return null;
  }

  /* ═══ 4 · ГЕРОЙ ═══════════════════════════════════════════════════ */

  function поставитьГероя(ключДороги, доля) {
    const д = поКлючу[ключДороги];
    герой = { дорога: д, s: д.длина * доля, вперёд: 1, v: 0, пройдено: 0 };
    маршрут = []; приходе = null;
    убратьМетку();
  }

  /* Куда идти по этой дороге и в какую сторону. На кольце путь
     считается в обе стороны: если разница больше половины длины —
     короче идти назад. Это и даёт выбор направления. */
  function разница(дорога, откуда, куда) {
    let d = куда - откуда;
    if (дорога.круговое) {
      const п = дорога.длина;
      d = ((d % п) + п) % п;
      if (d > п / 2) d -= п;
    }
    return d;
  }

  function идтиК(ключДороги, sЦель, чтоПотом) {
    const шаги = найтиПуть(герой.дорога.ключ, ключДороги);
    if (шаги === null) return false;
    маршрут = шаги.map((ш) => ({ дорога: ш.дорога, s: ш.стык.sТам,
                                 стык: ш.стык.sЗдесь }));
    // на последней дороге идём не к стыку, а к цели
    if (маршрут.length) маршрут[маршрут.length - 1].конец = sЦель;
    else маршрут = [{ дорога: ключДороги, конец: sЦель }];
    приходе = чтоПотом || null;
    return true;
  }

  function шагГероя(сек) {
    if (!герой) return;
    const цельШаг = маршрут[0];
    if (!цельШаг) { герой.v = 0; return; }

    const наЭтой = цельШаг.дорога === герой.дорога.ключ;
    const цель = наЭтой ? (цельШаг.конец !== undefined ? цельШаг.конец : цельШаг.s)
                        : цельШаг.стык;
    const дорога = наЭтой ? герой.дорога : поКлючу[цельШаг.дорога];
    if (!наЭтой) {
      // мы ещё на прежней дороге и идём к её стыку
      const до = разница(герой.дорога, герой.s, цельШаг.стык);
      двигать(сек, до);
      if (Math.abs(разница(герой.дорога, герой.s, цельШаг.стык)) < 1) {
        герой.дорога = поКлючу[цельШаг.дорога];
        герой.s = цельШаг.s;
        /* Последний шаг снимать нельзя: на нём стоит цель у двери, и
           по ней герой ещё должен пройти. Снимешь раньше — он встанет
           на краю тропки, и окошко не откроется. */
        if (цельШаг.конец === undefined) маршрут.shift();
        else цельШаг.стык = undefined;
      }
      return;
    }
    const до = разница(дорога, герой.s, цель);
    двигать(сек, до);
    if (Math.abs(разница(дорога, герой.s, цель)) < 1) {
      герой.s = цель; герой.v = 0;
      маршрут.shift();
      if (!маршрут.length && приходе) { const п = приходе; приходе = null; п(); }
    }
  }

  /* Разгон и торможение. Тормозим по формуле v = √(2·a·остаток):
     герой замедляется перед дверью, а не втыкается в неё. */
  function двигать(сек, остаток) {
    const х = НАСТРОЙКИ.ход;
    const предел = х.предел * (герой.дорога.вес || 1);
    const путь = Math.abs(остаток);
    герой.вперёд = остаток >= 0 ? 1 : -1;

    const порог = Math.sqrt(2 * х.разгон * х.торможение * путь);
    герой.v = Math.min(предел, порог, герой.v + х.разгон * сек);
    const шаг = Math.min(путь, герой.v * сек);
    герой.s += шаг * герой.вперёд;
    герой.пройдено += шаг;
    if (герой.дорога.круговое) {
      const п = герой.дорога.длина;
      герой.s = ((герой.s % п) + п) % п;
    }
  }

  function точкаГероя() {
    const т = герой.дорога.элемент.getPointAtLength(герой.s);
    return { x: т.x, y: т.y };
  }

  /* ═══ 4а · СВОБОДНОЕ ХОЖДЕНИЕ ═════════════════════════════════════
     Нажал в любое место — герой идёт туда по дорогам.

     Устройство не менялось: у героя по-прежнему дорога и путь по ней,
     маршрут ищется обходом в ширину. Добавлено ровно одно — найти
     ближайшую точку СЕТИ ДОРОГ к тому месту, куда ткнули.          */

  /*  Экранная точка → мировая. Спрашиваем у самого svg, а не считаем
      из viewBox второй раз: две одинаковые формулы разойдутся при
      первой же правке камеры.                                      */
  function вМировые(с) {
    const св = $('мир');
    const т = св.createSVGPoint();
    т.x = с.clientX;
    т.y = с.clientY;
    return т.matrixTransform(св.getScreenCTM().inverse());
  }

  function наДороге(дорога, s) {
    const т = дорога.элемент.getPointAtLength(s);
    return { x: т.x, y: т.y };
  }

  /*  Долгота вдоль дороги, приведённая к её длине: на кольце путь
      замыкается, на луче и тропке упирается в концы.               */
  function приткнуть(дорога, s) {
    if (!дорога.круговое) return Math.min(Math.max(s, 0), дорога.длина);
    const п = дорога.длина;
    return ((s % п) + п) % п;
  }

  /*  Ближайшая точка сети дорог. Сперва грубый проход по длине каждой
      дороги, потом деления пополам вокруг лучшего — иначе метка
      встанет в стороне от того места, куда придёт герой.           */
  function ближайшаяТочка(куда) {
    const х = НАСТРОЙКИ.карта.хождение;
    let лучшее = null;

    const померить = (дорога, s) => {
      const т = наДороге(дорога, s);
      const d = Math.hypot(т.x - куда.x, т.y - куда.y);
      if (!лучшее || d < лучшее.d) лучшее = { дорога: дорога, s: s, d: d, точка: т };
    };

    for (const дорога of дороги) {
      const шагов = Math.max(1, Math.ceil(дорога.длина / х.грубыйШаг));
      for (let i = 0; i <= шагов; i++) померить(дорога, дорога.длина * i / шагов);
    }
    if (!лучшее) return null;

    let шаг = х.грубыйШаг;
    for (let раз = 0; раз < х.уточнений; раз++) {
      шаг /= 2;
      const д = лучшее.дорога;
      померить(д, приткнуть(д, лучшее.s - шаг));
      померить(д, приткнуть(д, лучшее.s + шаг));
    }
    return лучшее;
  }

  /*  МЕТКА СТАВИТСЯ В ТОЧКУ ДОРОГИ, а не туда, куда ткнули. Человек
      нажимает на снег между лучами; если метка останется в снегу, а
      герой встанет на дороге, это читается как поломка.            */
  function поставитьМетку(т) {
    const х = НАСТРОЙКИ.карта.хождение;
    const слой = $('метка');
    слой.textContent = '';
    const г = document.createElementNS(НП, 'g');
    г.setAttribute('class', 'метка-цели');
    г.setAttribute('transform',
      'translate(' + т.x.toFixed(1) + ',' + т.y.toFixed(1) + ')');
    г.innerHTML =
      '<circle cx="0" cy="0" r="' + х.меткаРадиус +
        '" fill="none" stroke-width="' + х.меткаТолщина + '"/>' +
      '<path d="M' + (-х.меткаЛуч) + ' 0H' + х.меткаЛуч +
        'M0 ' + (-х.меткаЛуч) + 'V' + х.меткаЛуч +
        '" stroke-width="' + х.меткаТолщина + '"/>';
    слой.appendChild(г);
  }

  function убратьМетку() { $('метка').textContent = ''; }

  /*  Нажатие в пустое место. Далёкое отбрасывается совсем: ни метки,
      ни движения — иначе тычок в угол уводит героя через полмира.

      Маршрут строится от той дороги, на которой герой СЕЙЧАС, поэтому
      новое нажатие на ходу перестраивает путь с места, а не с начала:
      этим занимается `идтиК`, ничего добавлять не нужно.            */
  function нажалиЗемлю(с) {
    if (!герой) return;
    const цель = ближайшаяТочка(вМировые(с));
    if (!цель || цель.d > НАСТРОЙКИ.карта.хождение.дальше) return;
    камера.свободна = false;
    поставитьМетку(цель.точка);
    идтиК(цель.дорога.ключ, цель.s, убратьМетку);
  }

  /* ═══ 5 · КАМЕРА ══════════════════════════════════════════════════ */

  function навести(x, y) { камера.цельX = x; камера.цельY = y; }

  function шагКамеры() {
    if (!камера.свободна && герой) {
      const т = точкаГероя();
      навести(т.x, т.y);
    }
    const к = НАСТРОЙКИ.камера.плавность;
    камера.x += (камера.цельX - камера.x) * к;
    камера.y += (камера.цельY - камера.y) * к;

    const обзор = НАСТРОЙКИ.камера.обзор;
    const окно = $('двор').getBoundingClientRect();
    const высота = обзор * (окно.height / Math.max(окно.width, 1));
    $('мир').setAttribute('viewBox',
      (камера.x - обзор / 2).toFixed(1) + ' ' + (камера.y - высота / 2).toFixed(1) +
      ' ' + обзор.toFixed(1) + ' ' + высота.toFixed(1));
  }

  /* ═══ 6 · ОТРИСОВКА ═══════════════════════════════════════════════ */

  function земля() {
    const слой = $('земля');
    слой.textContent = '';
    const ц = НАСТРОЙКИ.карта.центр;
    const внешнее = МИР.кольца[МИР.кольца.length - 1];
    const лес = document.createElementNS(НП, 'rect');
    лес.setAttribute('x', 0); лес.setAttribute('y', 0);
    лес.setAttribute('width', НАСТРОЙКИ.карта.холст);
    лес.setAttribute('height', НАСТРОЙКИ.карта.холст);
    лес.setAttribute('class', 'лес');
    слой.appendChild(лес);
    // от внешнего кольца к внутреннему: каждое следующее поверх
    for (let i = МИР.кольца.length - 1; i >= 0; i--) {
      const к = МИР.кольца[i];
      const круг = document.createElementNS(НП, 'circle');
      круг.setAttribute('cx', ц); круг.setAttribute('cy', ц);
      круг.setAttribute('r', к.радиус + НАСТРОЙКИ.карта.отступДома * 2);
      круг.setAttribute('fill', к.земля);
      слой.appendChild(круг);
    }
  }

  function домSVG(дом) {
    const н = НАСТРОЙКИ.карта, д = н.дом;
    const ш = н.ширинаДома;
    const в = дом.этажи * н.высотаЭтажа;
    const г = document.createElementNS(НП, 'g');
    г.setAttribute('class', 'дом ' + дом.состояние);
    г.setAttribute('data-дом', дом.ключ);
    г.setAttribute('transform',
      'translate(' + (дом.точка.x - ш / 2).toFixed(1) + ',' +
      (дом.точка.y - в - н.крыша).toFixed(1) + ')');

    const рамка = (класс, x, y, ширина, высота) =>
      '<rect class="' + класс + '" x="' + x + '" y="' + y +
      '" width="' + ширина + '" height="' + высота + '"/>';

    let d = '<ellipse class="площадка" cx="' + ш / 2 + '" cy="' + (в + н.крыша) +
            '" rx="' + ш / 2 + '" ry="' + н.высотаЭтажа / 2 + '"/>';

    if (дом.состояние === МИР.состояния.свободно) {
      const низ = в + н.крыша;
      const верх = низ - н.высотаЭтажа * д.каркасЭтажей;
      d += '<path class="каркас" d="M' + д.каркасОтступ + ' ' + низ + 'V' + верх +
           ' M' + (ш - д.каркасОтступ) + ' ' + низ + 'V' + верх +
           ' M' + д.каркасКрая + ' ' + верх + 'H' + (ш - д.каркасКрая) + '"/>';
    } else {
      d += рамка('стены', 0, н.крыша, ш, в);
      d += рамка('стены-тень', ш * д.теньСправа, н.крыша, ш * (1 - д.теньСправа), в);
      for (let э = 1; э < дом.этажи; э++) {
        const y = н.крыша + э * н.высотаЭтажа;
        d += '<path class="поясок" d="M0 ' + y + 'H' + ш + '"/>';
      }
      for (let э = 0; э < дом.этажи; э++) {
        const y = н.крыша + э * н.высотаЭтажа + н.высотаЭтажа * д.окноСверху;
        const высота = н.высотаЭтажа * д.окноВысота;
        d += рамка('оконце', ш * д.окноЛево, y, ш * д.окноШирина, высота);
        d += рамка('оконце', ш * д.окноПраво, y, ш * д.окноШирина, высота);
      }
      // свет всегда слева сверху: светлый скат слева, тёмный справа
      d += '<path class="скат-свет" d="M0 ' + н.крыша + 'L' + ш / 2 + ' 0L' +
           ш / 2 + ' ' + н.крыша + 'Z"/>';
      d += '<path class="скат-тень" d="M' + ш + ' ' + н.крыша + 'L' + ш / 2 +
           ' 0L' + ш / 2 + ' ' + н.крыша + 'Z"/>';
      d += рамка('труба', ш * д.трубаЛево, н.крыша * д.трубаСверху,
                 ш * д.трубаШирина, н.крыша * д.трубаВысота);
    }
    г.innerHTML = d;
    return г;
  }

  function вывеска(дом) {
    const н = НАСТРОЙКИ.карта, д = н.дом;
    const в = дом.этажи * н.высотаЭтажа;
    const г = document.createElementNS(НП, 'g');
    г.setAttribute('class', 'вывеска ' + дом.состояние);
    г.setAttribute('transform', 'translate(' + дом.точка.x.toFixed(1) + ',' +
      (дом.точка.y - в - н.крыша - н.высотаЭтажа * д.подписьВыше).toFixed(1) + ')');

    const свободно = дом.состояние === МИР.состояния.свободно;
    const цена = кольцоПо(дом.кольцо)[дом.сторона === МИР.стороны.внутри
      ? 'ценаВнутри' : 'ценаСнаружи'];
    const имя = свободно ? МИР.тексты.окошко_свободно_имя : дом.имя;
    const низ = свободно ? подставить(МИР.тексты.дом_цена, { цена: цена })
      : (дом.состояние === МИР.состояния.закрыт ? МИР.тексты.дом_закрыто : дом.занятие);
    const x = свободно ? 0 : -д.текстСдвиг;
    const край = свободно ? 'middle' : 'start';

    let d = '';
    if (!свободно) {
      d += '<use class="значок" href="#з-' + дом.занятие + '" x="' + (-д.значокСлева) +
           '" y="' + (-д.значокСверху) + '" width="' + д.значокРазмер +
           '" height="' + д.значокРазмер + '"/>';
    }
    d += '<text class="имя" x="' + x + '" y="0" text-anchor="' + край + '">' + имя + '</text>';
    d += '<text class="занятие" x="' + x + '" y="' + д.втораяСтрока +
         '" text-anchor="' + край + '">' + низ + '</text>';
    г.innerHTML = d;
    return г;
  }

  function постройки() {
    const слой = $('постройки');
    слой.textContent = '';
    // дальние дома рисуются раньше, ближние поверх
    const по = МИР.дома.slice().sort((а, б) => а.точка.y - б.точка.y);
    for (const дом of по) {
      слой.appendChild(домSVG(дом));
      слой.appendChild(вывеска(дом));
    }
  }

  function столбы() {
    const слой = $('столбы');
    слой.textContent = '';
    for (const к of МИР.кольца) {
      for (const угол of МИР.лучи) {
        const т = точка(к.радиус, угол);
        const г = document.createElementNS(НП, 'g');
        г.setAttribute('class', 'столб');
        г.setAttribute('data-столб', к.ключ);
        г.setAttribute('transform', 'translate(' + (т.x - НАСТРОЙКИ.ход.ростГероя / 2).toFixed(1) +
          ',' + (т.y - НАСТРОЙКИ.ход.ростГероя).toFixed(1) + ')');
        const с = НАСТРОЙКИ.карта.столб, р = НАСТРОЙКИ.ход.ростГероя;
        г.innerHTML = '<rect class="ловушка" x="' + (-с.ловушкаОтступ) + '" y="' +
          (-с.ловушкаОтступ) + '" width="' + (р + с.ловушкаЗапас) + '" height="' +
          (р + с.ловушкаЗапас) + '"/>' +
          '<use href="#з-столб" width="' + р + '" height="' + р + '"/>';
        слой.appendChild(г);
      }
    }
  }

  /*  Фигурка героя. Всё, что ей нужно, лежит в записи героя: три
      цвета и народ. В данные сборки карта не заглядывает.

      Если записи нет вовсе — рисуем в цветах по умолчанию, чтобы на
      карте всё равно кто-то стоял.                                */
  function фигураГероя() {
    const слой = $('фигура');
    слой.textContent = '';

    const р = НАСТРОЙКИ.ход.ростГероя, ф = НАСТРОЙКИ.карта.фигура;
    const з = ЗАПИСЬ() || {};
    const ц = НАСТРОЙКИ.цвета;
    // цвета приходят из записи, а запись человек правит руками
    const плащ  = цветИли(з.цветПлаща, ц.плащПоУмолчанию);
    const кожа  = цветИли(з.цветКожи,  ц.кожаПоУмолчанию);
    const волос = цветИли(з.цветВолос, ц.волосыПоУмолчанию);
    const народ = МИР.народы[з.народ];

    const в = (доля) => (-р * доля).toFixed(1);   // вверх — это минус
    const ш = (доля) => (р * доля).toFixed(1);

    const голова = в(ф.голова), радиус = ш(ф.головаРадиус);

    /* Знак народа: тот же путь, что на вывесках, сжатый до плаща. */
    const доляЗнака = (р * ф.знакРазмер) / ф.знакХолст;
    const знак = народ
      ? '<g class="знак-народа" transform="translate(' +
        (-р * ф.знакРазмер / 2).toFixed(1) + ',' + в(ф.знакВерх) +
        ') scale(' + доляЗнака.toFixed(2) + ')" fill="none" stroke-width="' +
        ф.знакТолщина + '" stroke-linejoin="round">' + народ.знак + '</g>'
      : '';

    const г = document.createElementNS(НП, 'g');
    г.setAttribute('class', 'герой-на-карте');
    г.innerHTML =
      '<ellipse class="тень-героя" cx="0" cy="0" rx="' + ш(ф.теньШирина) +
        '" ry="' + ш(ф.теньВысота) + '"/>' +
      '<g class="' + ф.имяТулова + '">' +

        /* плащ — вся фигура и есть плащ: на этом размере читается
           силуэт, а не руки и ноги */
        '<path d="M0 ' + в(ф.плечи) + 'L' + ш(ф.полуширина) + ' ' + в(ф.подол) +
          'L' + в(ф.полуширина) + ' ' + в(ф.подол) + 'Z" fill="' + плащ + '"/>' +

        /* правая пола темнее: свет у нас всегда слева сверху */
        '<path d="M0 ' + в(ф.плечи) + 'L' + ш(ф.полуширина) + ' ' + в(ф.подол) +
          'L0 ' + в(ф.подол) + 'Z" fill="#000" opacity="' + ф.затемнение + '"/>' +

        знак +

        '<circle cx="0" cy="' + голова + '" r="' + радиус + '" fill="' + кожа + '"/>' +

        /* волосы — верхняя половина головы, лицо остаётся снизу */
        '<path d="M' + (-р * ф.головаРадиус).toFixed(1) + ' ' + голова +
          'A' + радиус + ' ' + радиус + ' 0 0 1 ' + радиус + ' ' + голова +
          'Z" fill="' + волос + '"/>' +

        '<circle class="ободок" cx="0" cy="' + голова + '" r="' + радиус +
          '" fill="none" stroke-width="' + ш(ф.ободок) + '"/>' +
      '</g>';

    /*  Настоящая фигура заменяет рисованную, когда картинка
        загрузится. Не загрузилась — рисованная остаётся.          */
    фигураИзБиблиотеки(з, г, г.querySelector('.' + ф.имяТулова));
    слой.appendChild(г);
    return г;
  }


  /*  МЕДАЛЬОН НАД ФИГУРКОЙ — лицо героя в мире.

      Фигурка рисуется кодом и лица не имеет: на её размере лицо было
      бы пятном. Лицо живёт в кружке над ней.

      Картинка берётся готовой обрезкой по голове, а не портретом
      целиком: в кружке этого размера целый портрет нечитаем — лицо
      занимает восемь точек из двадцати шести.

      Нет картинки — нет и кружка. Мир от этого не ломается: фигурка,
      её цвета и знак народа на месте.                              */
  /*  ФИГУРА ГЕРОЯ ИЗ БИБЛИОТЕКИ.

      По карте ходит сам герой, а не рисованная фигурка: фон у картинки
      вырезан, и она встаёт прямо на землю. Медальон над головой
      отменён вместе с рисованным заменителем — он был нужен, только
      пока фигуру нельзя было вырезать из фона.

      СНАЧАЛА ПРОВЕРЯЕМ, ЧТО КАРТИНКА ЕСТЬ. Библиотека собрана не вся,
      и под иной выбор файла может не быть вовсе. Тогда остаётся
      фигурка, нарисованная кодом: она работала до библиотеки и должна
      работать после. Битой картинки на карте быть не должно.

      Адрес приходит из записи, а запись человек правит руками —
      поэтому узлом и через `setAttribute`, а не склейкой строки.    */
  function фигураИзБиблиотеки(з, куда, рисованная) {
    const адрес = з.фигураИзБиблиотеки;
    if (!адрес) return;

    const проба = new Image();
    проба.onload = () => {
      const р = НАСТРОЙКИ.ход.ростГероя;
      const ширина = р * проба.naturalWidth / проба.naturalHeight;
      const кадр = document.createElementNS(НП, 'image');
      кадр.setAttribute('x', (-ширина / 2).toFixed(1));
      кадр.setAttribute('y', (-р).toFixed(1));     // ступни на земле
      кадр.setAttribute('width', ширина.toFixed(1));
      кадр.setAttribute('height', р.toFixed(1));
      кадр.setAttribute('class', НАСТРОЙКИ.карта.фигура.имяКартинки);
      кадр.setAttribute('href', адрес);
      рисованная.remove();          // заменяем, а не кладём поверх
      куда.appendChild(кадр);
    };
    проба.src = адрес;
  }

  /*  Цвет из записи героя — только настоящий цвет.

      Три цвета фигурки лежат в записи готовыми кодами, а запись
      человек правит руками. Значение вроде `red" onload="…` в
      склеенной строке закрыло бы кавычку и стало разметкой. Не
      похоже на цвет — берём запасной.                             */
  function цветИли(значение, запасной) {
    return (typeof значение === 'string' &&
            НАСТРОЙКИ.карта.цветПравило.test(значение)) ? значение : запасной;
  }

  /* ═══ 7 · ПОДСТАНОВКА ═════════════════════════════════════════════ */

  function подставить(шаблон, значения) {
    return шаблон.replace(/\{([^{}]+)\}/g, (всё, ключ) =>
      (ключ in значения) ? значения[ключ] : всё);
  }

  /* ═══ 8 · КАДР ════════════════════════════════════════════════════ */

  /* Один шаг мира. Вынесен наружу нарочно: так движение проверяется
     без кадров анимации, и так же им можно будет управлять извне —
     например, останавливать мир, когда открыт стол. */
  function шаг(сек) {
    шагГероя(сек);
    шагКамеры();
    if (герой) {
      const т = точкаГероя();
      const х = НАСТРОЙКИ.ход;
      const качание = Math.sin(герой.пройдено / х.качаниеДелитель) *
        х.качаниеРазмах * (герой.v / х.предел);
      const фигура = $('фигура').firstChild;
      if (фигура) {
        фигура.setAttribute('transform',
          'translate(' + т.x.toFixed(1) + ',' + (т.y - качание).toFixed(1) + ')' +
          ' scale(' + герой.вперёд + ',1)');
      }
    }
  }

  function тик(время) {
    const сек = Math.min((время - прошлое) / НАСТРОЙКИ.карта.мсВСекунде,
                         НАСТРОЙКИ.карта.кадрМакс);
    прошлое = время;
    шаг(сек);
    кадр = requestAnimationFrame(тик);
  }

  /* ═══ 9 · СОБЫТИЯ ═════════════════════════════════════════════════ */

  function показатьПолосу(текст) {
    const п = $('полоса');
    п.textContent = текст;
    п.hidden = false;
    clearTimeout(полосаТаймер);
    полосаТаймер = setTimeout(() => { п.hidden = true; },
      НАСТРОЙКИ.карта.указательМс);
  }

  function повеситьСобытия() {
    const двор = $('двор');
    let x0 = 0, y0 = 0, ехали = 0, тянем = false;

    двор.addEventListener('pointerdown', (с) => {
      тянем = true; ехали = 0; x0 = с.clientX; y0 = с.clientY;
    });
    window.addEventListener('pointermove', (с) => {
      if (!тянем) return;
      const дх = с.clientX - x0, ду = с.clientY - y0;
      ехали = Math.max(ехали, Math.hypot(дх, ду));
      if (ехали > НАСТРОЙКИ.карта.порогКлика) {
        // любое касание отпускает камеру: иначе не осмотреться
        камера.свободна = true;
        const обзор = НАСТРОЙКИ.камера.обзор;
        const окно = двор.getBoundingClientRect();
        навести(камера.цельX - дх * обзор / окно.width,
                камера.цельY - ду * обзор / окно.width);
        x0 = с.clientX; y0 = с.clientY;
      }
    }, { passive: true });
    window.addEventListener('pointerup', () => { тянем = false; });

    двор.addEventListener('click', (с) => {
      if (ехали > НАСТРОЙКИ.карта.порогКлика) return;
      const столб = с.target.closest('[data-столб]');
      if (столб) { нажалиСтолб(столб.dataset.столб); return; }
      const дом = с.target.closest('[data-дом]');
      if (дом) { нажалиДом(дом.dataset.дом); return; }
      нажалиЗемлю(с);
    });

    $('к-герою').addEventListener('click', () => { камера.свободна = false; });

    $('кольца-кнопки').addEventListener('click', (с) => {
      const кн = с.target.closest('[data-кольцо]');
      if (!кн) return;
      камера.свободна = true;
      const к = кольцоПо(кн.dataset.кольцо);
      const т = точка(к.радиус, -НАСТРОЙКИ.карта.полныйОборот / 2 / 2);
      навести(т.x, т.y);
    });
  }

  function нажалиСтолб(ключКольца) {
    const номер = МИР.кольца.findIndex((к) => к.ключ === ключКольца);
    // столб рассказывает про соседнее кольцо: наружу, а с края — внутрь
    const сосед = МИР.кольца[номер + 1] || МИР.кольца[номер - 1];
    const занятия = сосед.занятия.join(', ');
    показатьПолосу(подставить(МИР.тексты.указатель, {
      куда: сосед.куда, прозвище: сосед.прозвище,
      цена: сосед.ценаСнаружи,
      занятия: занятия.charAt(0).toUpperCase() + занятия.slice(1)
    }));
  }

  function нажалиДом(ключ) {
    const дом = МИР.дома.find((д) => д.ключ === ключ);
    if (!дом) return;
    камера.свободна = false;
    убратьМетку();          // шли в поле, передумали и пошли в дом
    const тропка = поКлючу[дом.тропка];
    идтиК(дом.тропка, тропка.длина, () => открытьОкошко(дом));
  }

  function открытьОкошко(дом) {
    const т = МИР.тексты;
    const цена = кольцоПо(дом.кольцо)[дом.сторона === МИР.стороны.внутри ? 'ценаВнутри' : 'ценаСнаружи'];
    const свободно = дом.состояние === МИР.состояния.свободно;
    const заголовок = свободно ? т.окошко_свободно_имя : дом.имя;
    const текст = свободно ? подставить(т.окошко_свободно, { цена: цена })
      : (дом.состояние === МИР.состояния.закрыт ? т.окошко_закрыт
         : подставить(т.окошко_открыт, { занятие: дом.занятие }));

    /*  Окошко и есть карточка входа в лавку: имя, чем занимаются и
        кнопка «войти». Кнопка появляется только у открытого дома, за
        которым лавка действительно построена. У остальных окошко
        остаётся прежним — так и было в задании на карту.           */
    const кнопки = [[т.закрыть, null, false]];
    const открыт = дом.состояние === МИР.состояния.открыт;
    if (открыт && window.ЛАВКИ && window.ЛАВКИ.есть(дом.занятие)) {
      кнопки.push([т.окошко_войти, () => window.ЛАВКИ.открыть(дом), true]);
    }
    window.ОКОШКО(заголовок, текст, кнопки);
  }

  /* ═══ 10 · ЗАПУСК ═════════════════════════════════════════════════ */

  function кнопкиКолец() {
    $('кольца-кнопки').innerHTML = МИР.кольца.map((к, i) =>
      '<button data-кольцо="' + к.ключ + '">' + (i + 1) + '</button>').join('');
  }

  function показать() {
    земля();
    стена();
    построитьДороги();
    постройки();
    столбы();
    фигураГероя();
    кнопкиКолец();
    if (!герой) поставитьГероя(МИР.кольца[0].ключ, 0);
    if (!камера) {
      const т = точкаГероя();
      камера = { x: т.x, y: т.y, цельX: т.x, цельY: т.y, свободна: false };
    }
    повеситьСобытия();
    прошлое = performance.now();
    cancelAnimationFrame(кадр);
    кадр = requestAnimationFrame(тик);
  }

  /* Где герой: ключ дороги и пройденный по ней путь. Координат нет. */
  function где() {
    return герой ? { дорога: герой.дорога.ключ, s: герой.s,
                     идёт: маршрут.length > 0, v: герой.v } : null;
  }

  /*  Герой мог смениться в сборке. Перезагрузки страницы больше нет,
      поэтому фигурку пересобираем по требованию.                  */
  function перерисоватьГероя() {
    if (!$('фигура').firstChild) return;   // карта ещё не строилась
    фигураГероя();
  }

  return { показать: показать, шаг: шаг, где: где, идтиК: идтиК,
           перерисоватьГероя: перерисоватьГероя };
})();
